-module(bmscl_authority_broker).
-behaviour(gen_server).

-export([
    start_link/0,
    install_grants/2,
    install_abi/4,
    grant/2,
    authorize/3
]).
-export([init/1, handle_call/3, handle_cast/2, handle_info/2, terminate/2, code_change/3]).

-record(state, {
    entries = #{},
    monitors = #{}
}).

start_link() ->
    gen_server:start_link({local, ?MODULE}, ?MODULE, [], []).

install_grants(Pid, Grants) when is_pid(Pid), is_map(Grants) ->
    call({install, Pid, grants, Grants}).

install_abi(Pid, Allowed, Tokens, Meta)
  when is_pid(Pid), is_list(Allowed), is_map(Tokens), is_map(Meta) ->
    call({install, Pid, abi, #{allowed => Allowed, tokens => Tokens, meta => Meta}}).

grant(Pid, Name) when is_pid(Pid), is_binary(Name) ->
    call({grant, Pid, Name}).

authorize(Pid, Name, Token) when is_pid(Pid), is_binary(Name), is_binary(Token) ->
    call({authorize, Pid, Name, Token}).

init([]) ->
    {ok, #state{}}.

handle_call({install, Pid, Section, Value}, {Pid, _Tag}, State0)
  when Section =:= grants; Section =:= abi ->
    case is_process_alive(Pid) of
        false -> {reply, {error, invocation_not_alive}, State0};
        true ->
            {Entry0, State1} = ensure_entry(Pid, State0),
            case maps:find(Section, Entry0) of
                error ->
                    Entry1 = maps:put(Section, Value, Entry0),
                    Entries1 = maps:put(Pid, Entry1, State1#state.entries),
                    {reply, ok, State1#state{entries = Entries1}};
                {ok, Value} ->
                    {reply, ok, State1};
                {ok, _Other} ->
                    %% Once trusted setup has installed a section, later code in
                    %% the same P3 can neither widen nor replace it.
                    {reply, {error, authority_already_installed}, State1}
            end
    end;
handle_call({install, _Pid, _Section, _Value}, _From, State) ->
    {reply, {error, authority_caller_mismatch}, State};
handle_call({grant, Pid, Name}, {Pid, _Tag}, State) ->
    Reply = case entry_section(Pid, grants, State) of
        {ok, Grants} ->
            case maps:find(Name, Grants) of
                {ok, Grant} -> {ok, Grant};
                error -> {error, capability_scope_not_admitted}
            end;
        error -> {error, capability_scope_not_installed}
    end,
    {reply, Reply, State};
handle_call({authorize, Pid, Name, Token}, {Pid, _Tag}, State) ->
    Reply = case entry_section(Pid, abi, State) of
        {ok, #{allowed := Allowed, tokens := Tokens, meta := Meta}} ->
            case lists:member(Name, Allowed) andalso maps:get(Name, Tokens, undefined) =:= Token of
                true -> {ok, Meta};
                false -> {error, invalid_capability_token}
            end;
        error -> {error, capability_not_admitted}
    end,
    {reply, Reply, State};
handle_call({grant, _Pid, _Name}, _From, State) ->
    {reply, {error, authority_caller_mismatch}, State};
handle_call({authorize, _Pid, _Name, _Token}, _From, State) ->
    {reply, {error, authority_caller_mismatch}, State};
handle_call(_Request, _From, State) ->
    {reply, {error, unsupported_call}, State}.

handle_cast(_Msg, State) -> {noreply, State}.

handle_info({'DOWN', Mon, process, _Pid, _Reason}, State0) ->
    case maps:take(Mon, State0#state.monitors) of
        error -> {noreply, State0};
        {Pid, Monitors1} ->
            Entries1 = maps:remove(Pid, State0#state.entries),
            State1 = State0#state{entries = Entries1, monitors = Monitors1},
            case maps:size(Entries1) =:= 0 andalso not app_running() of
                true -> {stop, normal, State1};
                false -> {noreply, State1}
            end
    end;
handle_info(_Info, State) -> {noreply, State}.

terminate(_Reason, _State) -> ok.
code_change(_OldVsn, State, _Extra) -> {ok, State}.

ensure_entry(Pid, State = #state{entries = Entries, monitors = Monitors}) ->
    case maps:find(Pid, Entries) of
        {ok, Entry} -> {Entry, State};
        error ->
            Mon = erlang:monitor(process, Pid),
            Entry = #{monitor => Mon},
            {Entry, State#state{
                entries = maps:put(Pid, Entry, Entries),
                monitors = maps:put(Mon, Pid, Monitors)
            }}
    end.

entry_section(Pid, Section, #state{entries = Entries}) ->
    case maps:find(Pid, Entries) of
        {ok, Entry} -> maps:find(Section, Entry);
        error -> error
    end.

call(Request) ->
    case whereis(?MODULE) of
        Pid when is_pid(Pid) -> gen_server:call(Pid, Request);
        undefined ->
            case app_running() of
                true -> {error, authority_broker_unavailable};
                false ->
                    case gen_server:start({local, ?MODULE}, ?MODULE, [], []) of
                        {ok, Pid} -> gen_server:call(Pid, Request);
                        {error, {already_started, Pid}} -> gen_server:call(Pid, Request);
                        {error, Reason} -> {error, {authority_broker_start_failed, Reason}}
                    end
            end
    end.

app_running() ->
    lists:keymember(bmscl_supervisor, 1, application:which_applications()).

-module(bmscl_aws_lambda_event).

-export([decode/2, encode_response/1, encode_error/1, encode_runtime_error/1]).

decode(Event, Meta0) when is_map(Event), is_map(Meta0) ->
    case maps:get(<<"version">>, Event, undefined) of
        <<"2.0">> -> decode_http_api_v2(Event, Meta0);
        Version -> {error, {unsupported_aws_event_version, Version}}
    end;
decode(_, _) ->
    {error, invalid_aws_event}.

decode_http_api_v2(Event, Meta0) ->
    RequestContext = maps:get(<<"requestContext">>, Event, #{}),
    Http = maps:get(<<"http">>, RequestContext, #{}),
    Method = maps:get(<<"method">>, Http, undefined),
    Path = maps:get(<<"rawPath">>, Event, undefined),
    Query = maps:get(<<"rawQueryString">>, Event, <<>>),
    Headers0 = maps:get(<<"headers">>, Event, #{}),
    Cookies = maps:get(<<"cookies">>, Event, []),
    case {valid_query(Query), aws_headers(Headers0, Cookies), body(Event)} of
        {true, {ok, Headers}, {ok, Body}} when is_binary(Path) ->
            Url = case Query of
                <<>> -> Path;
                _ -> <<Path/binary, "?", Query/binary>>
            end,
            Meta = Meta0#{
                provider => maps:get(provider, Meta0, <<"aws-lambda">>),
                invocation_id => invocation_id(RequestContext, Meta0)
            },
            {ok, #{method => Method,
                   route_path => Path,
                   url => Url,
                   headers => Headers,
                   body => Body,
                   meta => Meta}};
        {false, _, _} -> {error, invalid_raw_query_string};
        {_, {error, Reason}, _} -> {error, Reason};
        {_, _, {error, Reason}} -> {error, Reason};
        _ -> {error, invalid_aws_http_event}
    end.

encode_response(#{status := Status, headers := Headers, body := Body})
  when is_integer(Status), is_list(Headers), is_binary(Body) ->
    case response_headers(Headers, #{}, []) of
        {ok, HeaderMap, Cookies} ->
            {ok, jsx:encode(#{
                <<"statusCode">> => Status,
                <<"headers">> => HeaderMap,
                <<"cookies">> => lists:reverse(Cookies),
                <<"body">> => base64:encode(Body),
                <<"isBase64Encoded">> => true
            })};
        {error, Reason} -> {error, Reason}
    end;
encode_response(_) ->
    {error, invalid_provider_response}.

encode_error(_Reason) ->
    %% Provider-facing errors are deliberately generic. Internal exception
    %% terms and stack traces stay in trusted telemetry rather than crossing the
    %% public invocation boundary.
    jsx:encode(#{
        <<"statusCode">> => 500,
        <<"headers">> => #{<<"content-type">> => <<"application/json">>},
        <<"body">> => <<"{\"error\":\"internal_error\"}">>,
        <<"isBase64Encoded">> => false
    }).

encode_runtime_error(_Reason) ->
    jsx:encode(#{
        <<"errorMessage">> => <<"BeamScale provider runtime failed">>,
        <<"errorType">> => <<"BmsclProviderRuntimeError">>,
        <<"stackTrace">> => []
    }).

aws_headers(Headers, Cookies) when is_map(Headers), is_list(Cookies), length(Cookies) =< 64 ->
    case bmscl_provider_http:normalize_headers(Headers) of
        {error, Reason} -> {error, Reason};
        {ok, Normalized} ->
            case cookie_header(Cookies) of
                none -> {ok, Normalized};
                {ok, Cookie} ->
                    bmscl_provider_http:normalize_headers(
                      Normalized ++ [[<<"cookie">>, Cookie]]);
                {error, Reason} -> {error, Reason}
            end
    end;
aws_headers(_, _) ->
    {error, invalid_aws_headers}.

cookie_header([]) -> none;
cookie_header(Cookies) ->
    case lists:all(fun valid_cookie/1, Cookies) of
        true ->
            {ok, iolist_to_binary(lists:join(<<"; ">>, Cookies))};
        false ->
            {error, invalid_aws_cookie}
    end.

valid_cookie(Cookie) when is_binary(Cookie), byte_size(Cookie) =< 4096 ->
    binary:match(Cookie, <<"\r">>) =:= nomatch andalso
    binary:match(Cookie, <<"\n">>) =:= nomatch andalso
    binary:match(Cookie, <<0>>) =:= nomatch;
valid_cookie(_) -> false.

body(Event) ->
    Value = maps:get(<<"body">>, Event, <<>>),
    IsBase64 = maps:get(<<"isBase64Encoded">>, Event, false),
    case {Value, IsBase64} of
        {undefined, _} -> {ok, <<>>};
        {null, _} -> {ok, <<>>};
        {Bin, false} when is_binary(Bin) -> {ok, Bin};
        {Bin, true} when is_binary(Bin) ->
            try {ok, base64:decode(Bin)}
            catch _:_ -> {error, invalid_base64_request_body}
            end;
        _ -> {error, invalid_aws_request_body}
    end.

valid_query(Query) when is_binary(Query), byte_size(Query) =< 4096 ->
    binary:match(Query, <<"#">>) =:= nomatch andalso
    binary:match(Query, <<0>>) =:= nomatch andalso
    not lists:any(fun(Byte) -> Byte < 32 orelse Byte =:= 127 end,
                  binary_to_list(Query));
valid_query(_) -> false.

invocation_id(RequestContext, Meta) ->
    case maps:get(invocation_id, Meta, undefined) of
        Value when is_binary(Value), byte_size(Value) > 0 -> Value;
        _ ->
            case maps:get(<<"requestId">>, RequestContext, undefined) of
                Value when is_binary(Value), byte_size(Value) > 0, byte_size(Value) =< 128 ->
                    Value;
                _ ->
                    binary:encode_hex(crypto:strong_rand_bytes(16), lowercase)
            end
    end.

response_headers([], Acc, Cookies) ->
    {ok, Acc, Cookies};
response_headers([[Name0, Value] | Rest], Acc0, Cookies)
  when is_binary(Name0), is_binary(Value) ->
    Name = unicode:characters_to_binary(string:lowercase(binary_to_list(Name0))),
    case Name of
        <<"set-cookie">> ->
            response_headers(Rest, Acc0, [Value | Cookies]);
        _ ->
            Acc1 = case maps:find(Name, Acc0) of
                {ok, Previous} ->
                    maps:put(Name, <<Previous/binary, ",", Value/binary>>, Acc0);
                error ->
                    maps:put(Name, Value, Acc0)
            end,
            response_headers(Rest, Acc1, Cookies)
    end;
response_headers([{Name, Value} | Rest], Acc, Cookies) ->
    response_headers([[Name, Value] | Rest], Acc, Cookies);
response_headers(_, _, _) ->
    {error, invalid_response_headers}.
